// Generated by vibelang from src/features/coedit/schema.ts; the migrate flow writes it again with each batch.
import { Schema } from "effect";
// Co-editing's rows (decision 0013 §4, docs/features/coedit.md).
/** One update of a text, as Electric syncs it: its id and the update, as base64. Read-only. */
export const TextUpdate = Schema.Struct({ id: Schema.String, data: Schema.String });
/** A text's scope, as the routes take it. */
export const Scope = Schema.Union([
    Schema.Struct({ conversation: Schema.String }),
    Schema.Struct({ run: Schema.String }),
]);
/**
 * One update the outbox holds until ChatApi takes it, as its write's optimistic row: kept by the outbox across
 * reloads, so a text a device typed into offline still has it. `seed` marks a file's first content.
 */
export const Sending = Schema.Struct({
    id: Schema.String,
    textId: Schema.String,
    scope: Scope,
    data: Schema.String,
    seed: Schema.Boolean,
});
/** A place in a text: where a selection started (`anchor`) and where its caret is (`head`); equal for a caret. */
export const Selection = Schema.Struct({ anchor: Schema.Number, head: Schema.Number });
/** Someone else's caret and selection in a text: one per connection, keyed and coloured by its id. */
export const Collaborator = Schema.Struct({
    id: Schema.String,
    name: Schema.String,
    anchor: Schema.Number,
    head: Schema.Number,
});
/**
 * One text this tab has open, by its id:
 * - `kind` and `key`: what it is, a conversation's prompt (`key` the conversation, `home` for the home one), a file
 *   (`key` its path) or a run's answer box (`key` the run);
 * - `status`: `loading` until its updates arrive (a file also until its first content is in), `ready`, or `failed`
 *   when a file can't be read (`failure` says why);
 * - `shown` while this tab is in its room, as a page that shows it is;
 * - `stored` once every update this tab made is in the device's outbox, so a reload finds it;
 * - `text`, this person's `selection` as it now stands, and everyone else's carets (`collaborators`);
 * - `saving` while this tab's Save of a file runs, `saveFailed` when it last failed, and `saved` while the text is what
 *   the last Save, anyone's, wrote: the text's `saved` mark (`savedMarkOf`) is this text's.
 */
export const Shared = Schema.Struct({
    id: Schema.String,
    kind: Schema.Literals(["prompt", "file", "answer"]),
    key: Schema.String,
    status: Schema.Literals(["loading", "ready", "failed"]),
    shown: Schema.Boolean,
    stored: Schema.Boolean,
    failure: Schema.NullOr(Schema.Literals(["too_large", "unavailable", "forbidden"])),
    text: Schema.String,
    selection: Schema.NullOr(Selection),
    collaborators: Schema.Array(Collaborator),
    saving: Schema.Boolean,
    saveFailed: Schema.Boolean,
    saved: Schema.Boolean,
});
